"""Derive SkyyAccessories/build_skyyaccessories_0.5.32.py from the GENERATED SkyyAccessories 0.5.31 (build_skyyaccessories_0.5.31.py = the
tools/deploy_set.py SET pin, generated by tools/accessories_0_5_31_patch.py - edit the patch, never a generated script). Every anchor is
asserted once; at the end every change is undone on a copy and compared with 0.5.31 (tools/soundpass_gen.Patch). Line endings kept.
Run:  python tools/accessories_0_5_32_patch.py   then   python SkyyAccessories/build_skyyaccessories_0.5.32.py   (never --deploy)
      then  python SkyyAccessories/test_skyyaccessories_0.5.32.py
"""
import os, sys

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
sys.path.insert(0, os.path.join(ROOT, "tools"))
import soundpass_gen as G
import skyyelem as EL

NOTE = '''0.5.32 (2026-10-22) = WYNN ELEMENTS, the SkyyAccessories part: SIX ELEMENT CHARM LINES (research/Wynn-Elements-Build-Spec.md 4.5; FULL round
  elem1 with SkyyMobs 0.1.17, SkyyGear 0.3.39, SkyyClasses 0.1.46, SkyyPets 0.4.10, SkyyMenu 0.3.45 - pin + roll back TOGETHER). Skyy
  (docs/answered/gear.md 2026-10-18 Q2, the popup "add an 'Elemental Power' buff charm plus single-element charms (e.g. a Fire charm that adds
  raw Fire spell damage)?"): "yes, have them start weak but get powerful!".
  1. FIVE SINGLE-ELEMENT LINES (style "T": drop-only first rarity like Strength / Crit, upgrades in the bag's Craft tab; ids
     Skyy_Talisman_<Element>_T1..T6, names "<Rarity> <Element> Accessory"): Earth, Thunder, Water, Fire, Air. Each gives that element's
     damage (% of the hit, SkyyGear 0.3.39's element part - always; with the Server Setup row elem.charmGate on only for an element the
     weapon deals) and that element's Defence (always): Normal .. Mythic 1 / 1 / 2 / 2 / 3 / 3 % and 3 / 5 / 7 / 9 / 11 / 13 Defence (weak ->
     powerful, Skyy; elem1fix: every second step grows the damage too;
     whole numbers - SkyyGear floors every gear:extra part; the damage fitted so the P5 split holds: tools/balance_model.py --elem).
  2. THE ELEMENTAL POWER CHARM (admin / config / id word Prism; players see "<Rarity> Elemental Accessory" + the tooltip
     "Elemental Power: adds every element to your hits" - elem1fix, Skyy's own name: the "Elemental Power buff charm"; line names are one word): Raw Elemental 1 / 1 / 1 / 2 / 2 / 2 % (every element). A charm line, not an Accessory Power (the Powers page holds its 15 Powers).
  3. gear:extra may now carry fEarth fThunder fWater fFire fAir dEarth dThunder dWater dFire dAir rElem (SkyyGear parses any S_KEY; 0.3.39
     makes them do something). Server Setup rows boost.<Element>.dmgPct / .defence, boost.Prism.allPct and the line switches line.<Element>
     come from the table (a file without the line = the default, no migration). The six lines' look = the vanilla crystal of their colour
     (Earth green, Thunder yellow, Water blue, Fire red, Air cyan, Prism white) - own icons later.
  SAVED DATA: none (new item ids; new rows read their defaults). No new class / command / system.
  ROLLBACK to 0.5.31: the 36 new charm ids become unknown items (an owned one stays in the bag as an unknown id - never roll back once one
  exists, the Fabled / Mythic rule of 0.5.30); roll back with the elem1 set.
'''
NEW_LINES = [   # (family = admin = line name, crystal, gem, Legendary upgrade inputs, flavour)
    ("Earth", "Green", "Rock_Gem_Emerald", "Moss clings to it, and it hums with the ground."),
    ("Thunder", "Yellow", "Rock_Gem_Topaz", "It crackles whenever a storm is near."),
    ("Water", "Blue", "Rock_Gem_Sapphire", "Always cool, always a little damp."),
    ("Fire", "Red", "Rock_Gem_Ruby", "Warm to the touch, even in the snow."),
    ("Air", "Cyan", "Rock_Gem_Zephyr", "It never quite rests in your palm."),
]
EL_DMG = [1, 1, 2, 2, 3, 3]          # elem1fix (was 1/1/1/2/2/2: flat steps); fitted to the P5 split (tools/balance_model.py --elem: Void Charms best / plain x1.25 +- 0.05)
EL_DEF = [3, 5, 7, 9, 11, 13]
PRISM = [1, 1, 1, 2, 2, 2]          # elem1fix (was 1/1/1/1/2/2)
SRC6 = ["Drop", "Combine", "Craft", "Boss", "Craft", "Craft"]
UPR = {"Earth": [[("Ingredient_Crystal_Green", 3), ("Ingredient_Bar_Copper", 4)], [("Ingredient_Crystal_Green", 5), ("Ingredient_Bar_Iron", 10)],
                 [("Rock_Gem_Emerald", 2), ("Ingredient_Life_Essence", 20), ("Ingredient_Bar_Thorium", 10)]],
       "Thunder": [[("Ingredient_Crystal_Yellow", 3), ("Ingredient_Bar_Copper", 4)], [("Ingredient_Lightning_Essence", 5), ("Ingredient_Bar_Iron", 10)],
                   [("Rock_Gem_Topaz", 2), ("Ingredient_Lightning_Essence", 10), ("Ingredient_Bar_Thorium", 10)]],
       "Water": [[("Ingredient_Crystal_Blue", 3), ("Ingredient_Bar_Copper", 4)], [("Ingredient_Water_Essence", 5), ("Ingredient_Bar_Iron", 10)],
                 [("Rock_Gem_Sapphire", 2), ("Ingredient_Water_Essence", 10), ("Ingredient_Bar_Thorium", 10)]],
       "Fire": [[("Ingredient_Crystal_Red", 3), ("Ingredient_Bar_Copper", 4)], [("Ingredient_Fire_Essence", 5), ("Ingredient_Bar_Iron", 10)],
                [("Rock_Gem_Ruby", 2), ("Ingredient_Fire_Essence", 10), ("Ingredient_Bar_Thorium", 10)]],
       "Air": [[("Ingredient_Crystal_Cyan", 3), ("Ingredient_Bar_Copper", 4)], [("Ingredient_Feathers_Light", 10), ("Ingredient_Bar_Iron", 10)],
               [("Rock_Gem_Zephyr", 2), ("Ingredient_Motes_Light", 5), ("Ingredient_Bar_Thorium", 10)]],
       "Prism": [[("Ingredient_Crystal_White", 3), ("Ingredient_Bar_Copper", 4)], [("Rock_Crystal_Iridescent_Small", 2), ("Ingredient_Bar_Silver", 5)],
                 [("Rock_Gem_Diamond", 2), ("Ingredient_Bar_Prisma", 5), ("Ingredient_Bar_Thorium", 10)]]}

P = G.Patch(os.path.join(ROOT, "SkyyAccessories", "build_skyyaccessories_0.5.31.py"),
            os.path.join(ROOT, "SkyyAccessories", "build_skyyaccessories_0.5.32.py"))
if "--out" in sys.argv:
    P.dst = os.path.abspath(sys.argv[sys.argv.index("--out") + 1])
assert P.has('VERSION = "0.5.31"') and P.has("tools/accessories_0_5_31_patch.py") and not P.has('"Prism"'), "not the generated SkyyAccessories 0.5.31 script"
SYS0, CMD0 = P.s.count("registerSystem("), P.s.count("registerCommand(")

P.rep('''"""SkyyAccessories 0.5.31 - build script (derived from the generated build_skyyaccessories_0.5.30.py by tools/accessories_0_5_31_patch.py -
edit the patch, not this file)
Run:   python build_skyyaccessories_0.5.31.py            -> SkyyAccessories/SkyyAccessories-0.5.31.jar   (deploys go through tools/deploy_set.py --yes)
Test:  python test_skyyaccessories_0.5.31.py             (the Normal quality colour + start twice on live data)
''', '''"""SkyyAccessories 0.5.32 - build script (derived from the generated build_skyyaccessories_0.5.31.py by tools/accessories_0_5_32_patch.py -
edit the patch, not this file)
Run:   python build_skyyaccessories_0.5.32.py            -> SkyyAccessories/SkyyAccessories-0.5.32.jar   (deploys go through tools/deploy_set.py --yes)
Test:  python test_skyyaccessories_0.5.32.py             (the six element charm lines + start twice on live data)

''' + NOTE + '''
0.5.31 (the base; generated by tools/accessories_0_5_31_patch.py):
''')
P.rep('VERSION = "0.5.31"', 'VERSION = "0.5.32"')

# ---------- the booster table: + the six lines (appended: every old index stays)
_rows = "".join('''    ("%s", "%s", "%s", "%s", "%s",
     [("dmgPct", "%s", %r), ("defence", "%s", %r)], %r, "%s", None, "T"),
''' % (f, f, f, c, g, EL.DMG_KEYS[EL.NAMES.index(f)], EL_DMG, EL.DEF_KEYS[EL.NAMES.index(f)], EL_DEF, SRC6, fl) for f, c, g, fl in NEW_LINES)
_rows += '''    ("Prism", "Prism", "Elemental", "White", "Rock_Gem_Diamond",
     [("allPct", "rElem", %r)], %r, "Light splits into every colour inside it.", None, "T"),
''' % (PRISM, SRC6)
P.rep('''     [("fallPct", "fallPct", [10, 16, 22, 28, 34, 40]), ("jumpPct", "jumpPct", [5, 8, 11, 14, 17, 20])], ["Craft", "Craft", "Chest", "Chest", "Craft", "Craft"],
     "Lighter than it has any right to be.", None, "T"),
]''', '''     [("fallPct", "fallPct", [10, 16, 22, 28, 34, 40]), ("jumpPct", "jumpPct", [5, 8, 11, 14, 17, 20])], ["Craft", "Craft", "Chest", "Chest", "Craft", "Craft"],
     "Lighter than it has any right to be.", None, "T"),
    # ---- 0.5.32 (elem1): the five single-element lines + Prism (all elements) - research/Wynn-Elements-Build-Spec.md 4.5, tools/skyyelem.py
''' + _rows + ''']
ELEM_LINES = ["Earth", "Thunder", "Water", "Fire", "Air", "Prism"]          # 0.5.32''')
_kinds = "".join('''    "%s": ("pct", True, 100, "gear:extra key %s - SkyyGear 0.3.39: +N %% of the hit as %s damage (always; elem.charmGate on: only with a %s weapon)"),
    "%s": ("flat", True, 1000, "gear:extra key %s - SkyyGear 0.3.39: %s Defence (the %s part of a hit on you x scale / (scale + Defence))"),
''' % (EL.DMG_KEYS[i], EL.DMG_KEYS[i], n, n, EL.DEF_KEYS[i], EL.DEF_KEYS[i], n, n) for i, n in enumerate(EL.NAMES))
_kinds += '''    "rElem": ("pct", True, 100, "gear:extra key rElem - SkyyGear 0.3.39: +N % of the hit as EVERY element (gated per element like a single line)"),
'''
P.rep('''    "jumpPct":      ("pct",  False, 100,  "movement protocol source accessories.talismans, jump (pct layer) - applied by MoveSync.sync"),
}''', '''    "jumpPct":      ("pct",  False, 100,  "movement protocol source accessories.talismans, jump (pct layer) - applied by MoveSync.sync"),
    # 0.5.32 (elem1): the element lines - SkyyGear 0.3.39 applies them (whole numbers, like str / def)
''' + _kinds + '''}''')
_ek = ", ".join('"%s"' % k for k in EL.DMG_KEYS + EL.DEF_KEYS + ["rElem"])
P.rep('''GEAR_ALLOW = ("str", "mp", "def", "cc", "cd")''', '''GEAR_ALLOW = ("str", "mp", "def", "cc", "cd", %s)          # 0.5.32: + the element keys (SkyyGear 0.3.39)''' % _ek)
P.rep('''STAT_GEAR = {"str": "str", "mp": "mp", "def": "def", "cc": "cc", "cd": "cd"}
GEAR_NEVER = ("dmg", "tdmg", "spd", "stam", "fEarth", "fFire", "fWater", "fAir", "fThunder", "lsteal")''',
      '''STAT_GEAR = {"str": "str", "mp": "mp", "def": "def", "cc": "cc", "cd": "cd"}
STAT_GEAR.update(dict((_k, _k) for _k in (%s)))          # 0.5.32
GEAR_NEVER = ("dmg", "tdmg", "spd", "stam", "lsteal")          # 0.5.32: the element keys left this list (SkyyGear 0.3.39 applies them)''' % _ek)
P.rep('''RIDERS = {"manaFloor": "manaPct", "cd": "cc", "jumpPct": "fallPct", "staminaRegen": "maxStamina"}''',
      '''RIDERS = {"manaFloor": "manaPct", "cd": "cc", "jumpPct": "fallPct", "staminaRegen": "maxStamina"}
RIDERS.update(dict((_d, _f) for _d, _f in zip(%r, %r)))          # 0.5.32: element Defence rides with its element damage''' % (EL.DEF_KEYS, EL.DMG_KEYS))
P.rep('''    assert len(BOOSTERS) + 2 <= BONUS_MAX, "the Bonuses well holds one row per line + 2 notes (%d lines)" % len(BOOSTERS)''',
      '''    assert len(BOOSTERS) + 2 <= BONUS_MAX, "the Bonuses well holds one row per line + 2 notes (%d lines)" % len(BOOSTERS)          # 0.5.32: 18''')
P.rep('''BONUS_MAX = 12    # 0.5: the Bonuses well: two columns of 6 short lines''', '''BONUS_MAX = 18    # 0.5: the Bonuses well: two columns of 6 short lines; 0.5.32: 18 (16 lines + 2 notes; AccGear.pageRows has no page since 0.5.22)''')
P.rep('''assert MAIN_SLOTS == 9 and 1 <= SLOTS_DEF <= CAP == 60 and PAGE_ROWS == 9 and BONUS_MAX == 12''', '''assert MAIN_SLOTS == 9 and 1 <= SLOTS_DEF <= CAP == 60 and PAGE_ROWS == 9 and BONUS_MAX == 18''')

# ---------- the fixed old-table checks: the first 10 lines / 14 entries as before, the six new ones after them
P.rep('''assert [_b[0] for _b in BOOSTERS] == ["Vitality", "Endurance", "Intelligence", "Regeneration", "Speed", "Strength", "MagicPower",
                                     "Defense", "Crit", "Feather"], "the five folded lines + the five part 2 lines"''',
      '''assert [_b[0] for _b in BOOSTERS] == ["Vitality", "Endurance", "Intelligence", "Regeneration", "Speed", "Strength", "MagicPower",
                                     "Defense", "Crit", "Feather"] + ELEM_LINES, "the five folded lines + the five part 2 lines + the six element lines (0.5.32)"''')
P.rep('''                     "4,6,9,11,14,16", "10,16,22,28,34,40", "5,8,11,14,17,20"], BOOST_DEF          # 0.5.30 (Balance P5 4.2.1: Normal x 1 / 1.6 / 2.2 / 2.8 / 3.4 / 4)''',
      '''                     "4,6,9,11,14,16", "10,16,22,28,34,40", "5,8,11,14,17,20"] + ["1,1,2,2,3,3", "3,5,7,9,11,13"] * 5 + ["1,1,1,2,2,2"], BOOST_DEF          # 0.5.30 (Balance P5 4.2.1: Normal x 1 / 1.6 / 2.2 / 2.8 / 3.4 / 4); 0.5.32: + the element lines''')
P.rep('''assert [_e[0] for _e in ENTRIES][7:] == ["Strength.flat", "MagicPower.flat", "Defense.flat", "Crit.chancePct", "Crit.damagePct",
                                         "Feather.fallPct", "Feather.jumpPct"], "the spec 5.8 part 2 entry names"''',
      '''assert [_e[0] for _e in ENTRIES][7:14] == ["Strength.flat", "MagicPower.flat", "Defense.flat", "Crit.chancePct", "Crit.damagePct",
                                         "Feather.fallPct", "Feather.jumpPct"], "the spec 5.8 part 2 entry names"
assert [_e[0] for _e in ENTRIES][14:] == [_x for _n in ELEM_LINES[:5] for _x in (_n + ".dmgPct", _n + ".defence")] + ["Prism.allPct"], "0.5.32: the element entries"''')
P.rep('''assert COMBAT_LINES == ["Brawler", "Runic", "Stonehide", "Razorfang"], COMBAT_LINES''',
      '''assert COMBAT_LINES == ["Brawler", "Runic", "Stonehide", "Razorfang"] + ELEM_LINES[:5] + ["Elemental"], COMBAT_LINES          # 0.5.32: + the element lines (elem1fix: Prism shows as Elemental)''')
P.rep('''assert len(OLD_IDS) == 25 and len(LEGACY_IDS) == 20 and set(FOLDED_IDS) < set(OLD_IDS) and len(NEW_IDS) == 20''',
      '''assert len(OLD_IDS) == 25 and len(LEGACY_IDS) == 20 and set(FOLDED_IDS) < set(OLD_IDS) and len(NEW_IDS) == 20 + 24          # 0.5.32: + 6 lines x 4''')
P.rep('''assert not set(NEW_IDS6) & set(OLD_IDS + LEGACY_IDS + LINE_IDS) and len(NEW_IDS6) == 20          # 0.5.30: Fabled + Mythic are new ids''',
      '''assert not set(NEW_IDS6) & set(OLD_IDS + LEGACY_IDS + LINE_IDS) and len(NEW_IDS6) == 20 + 12          # 0.5.30: Fabled + Mythic are new ids; 0.5.32: + 6 lines x 2''')
P.rep('''MP5_C = [("boost." + ENTRIES[_i][0], BOOST_DEF_529[_i], BOOST_DEF[_i], 0) for _i in range(len(ENTRIES)) if ENTRIES[_i][0] != "Health.pct"]''',
      '''MP5_C = [("boost." + ENTRIES[_i][0], BOOST_DEF_529[_i], BOOST_DEF[_i], 0) for _i in range(len(BOOST_DEF_529)) if ENTRIES[_i][0] != "Health.pct"]          # 0.5.32: the 0.5.29 entries only''')
P.rep('''assert _n30 == 20, _n30''', '''assert _n30 == 20 + 12, _n30          # 0.5.32: + the six element lines' Fabled / Mythic''')

# ---------- the drop-only upgrades (the new lines are drop-up like Strength / Crit)
P.rep('''DROP_UP = ["Strength", "MagicPower", "Defense", "Crit", "Feather"]''', '''DROP_UP = ["Strength", "MagicPower", "Defense", "Crit", "Feather"] + ELEM_LINES          # 0.5.32: + the element lines''')
P.rep('''assert sorted(DROP_UP) == sorted(_b[0] for _b in BOOSTERS if _b[9] == "T"), "the five part 2 lines drop at their first rarity"''',
      '''assert sorted(DROP_UP) == sorted(_b[0] for _b in BOOSTERS if _b[9] == "T"), "the part 2 + element lines drop at their first rarity"''')
P.rep('''assert sorted(DROP_UP_RECIPES) == sorted(DROP_UP) and all(len(_r) == 3 for _r in DROP_UP_RECIPES.values())''',
      '''DROP_UP_RECIPES.update(%r)          # 0.5.32: the element lines' Unique / Rare / Legendary steps (their crystal, essence, gem + the tier metal)
assert sorted(DROP_UP_RECIPES) == sorted(DROP_UP) and all(len(_r) == 3 for _r in DROP_UP_RECIPES.values())''' % UPR)

# ---------- texts: the tooltips + the short stat parts (Java)
P.rep('''            assert d.startswith('<color is="%s">' % STAT_GOOD) and "while in your Void Charms." in d.split("\\\\n")[0], "stat line first: " + d[:80]''',
      '''            assert d.startswith(tuple('<color is="%s">' % _c for _c in [STAT_GOOD] + @ELCOLS@)) and "while in your Void Charms." in d.split("\\\\n")[0], "stat line first: " + d[:80]          # elem1fix2: + the element colours'''.replace("@ELCOLS@", repr(sorted(EL.COLORS.values()))))
# elem1fix2: the element values in their element colour (Style Guide 15; tools/skyyelem.py COLORS) - _wc below, next to _w
_tips = "".join('''    "%s": lambda v: (_wc("%s", "+%%s%%%% %s damage" %% _n(v["%s"])) + " and " + _wc("%s", "+%%s %s Defence" %% _n(v["%s"])) + " while in your Void Charms.",          # ui-data (Style Guide 15 element colours)
                     "%s damage added to every hit you land." + TIP_NL + "%s Defence cuts the %s part of hits on you."),
''' % (EL.DMG_KEYS[i], EL.COLORS[n], n, EL.DMG_KEYS[i], EL.COLORS[n], n, EL.DEF_KEYS[i], n, n, n) for i, n in enumerate(EL.NAMES))
P.rep('''def _w(t):
    return '<color is="%s">%s</color>' % (STAT_GOOD, t)
''', '''def _w(t):
    return '<color is="%s">%s</color>' % (STAT_GOOD, t)
def _wc(c, t):          # 0.5.32 (elem1fix2): an element value in its element colour (Style Guide 15)
    return '<color is="%s">%s</color>' % (c, t)
''')
_tips += '''    "rElem": lambda v: (_w("+%s%% damage of every element" % _n(v["rElem"])) + " while in your Void Charms.",
                        "Elemental Power: adds every element to your hits." + TIP_NL + "Works with gear weapons or bare hands."),
'''
P.rep('''    "fallPct": lambda v: (_w("-%s%% fall damage" % _n(v["fallPct"])) + " and " + _w("+%s%% jump height" % _n(v["jumpPct"])) +
                          " while in your Void Charms.", "Softer landings and higher jumps, on top of Acrobatics."),
}''', '''    "fallPct": lambda v: (_w("-%s%% fall damage" % _n(v["fallPct"])) + " and " + _w("+%s%% jump height" % _n(v["jumpPct"])) +
                          " while in your Void Charms.", "Softer landings and higher jumps, on top of Acrobatics."),
    # 0.5.32 (elem1): the element lines
''' + _tips + '''}''')
P.rep('''        "def": '"+" + numText(v) + " Defense"',
    }''', '''        "def": '"+" + numText(v) + " Defense"',
        "rElem": '"+" + numText(v) + "% every element"',          # 0.5.32
    }''')
_pairs = "".join('''        "%s": ("%s", '"+" + numText(a) + "%% %s damage"', '"+" + numText(r) + " %s Defence"'),
''' % (EL.DMG_KEYS[i], EL.DEF_KEYS[i], n, n) for i, n in enumerate(EL.NAMES))
P.rep('''        "fallPct": ("jumpPct", '"-" + numText(a) + "% fall damage"', '"+" + numText(r) + "% jump height"'),
    }''', '''        "fallPct": ("jumpPct", '"-" + numText(a) + "% fall damage"', '"+" + numText(r) + "% jump height"'),
''' + _pairs + '''    }''')
P.rep('''            if kd in ("manaFloor", "cd", "jumpPct"):
                continue''', '''            if kd in ("manaFloor", "cd", "jumpPct") or kd in %r:          # 0.5.32: + the element Defence riders
                continue''' % (EL.DEF_KEYS,))

# ---------- the icons: the six new lines use their vanilla crystal look (no own painter yet - tools/art/make_accessory_icons.py has the 10 + Lantern)
P.rep('''assert sorted(_l[1] for _l in MAI.LINES) == sorted([_b[0] for _b in BOOSTERS] + [LAN_FAM]), [_l[1] for _l in MAI.LINES]''',
      '''assert sorted(_l[1] for _l in MAI.LINES) == sorted([_b[0] for _b in BOOSTERS if _b[0] not in ELEM_LINES] + [LAN_FAM]), [_l[1] for _l in MAI.LINES]          # 0.5.32: the element lines have no own icon yet''')
P.rep('''    icons = [None] + [OWN_ICON[(fam, _t)] for _t in range(1, 5)]   # 0.5.7: our own icons (the vanilla ones above stay checked, unused)''',
      '''    if fam not in ELEM_LINES:          # 0.5.32: the element lines keep the vanilla crystal icons (own art later)
        icons = [None] + [OWN_ICON[(fam, _t)] for _t in range(1, 5)]   # 0.5.7: our own icons (the vanilla ones above stay checked, unused)''')

P.rep('''     "Off = %s add nothing (SkyyGear applies their stats)." % " and ".join(
         [", ".join(COMBAT_LINES[:-1]), COMBAT_LINES[-1]] if len(COMBAT_LINES) > 1 else COMBAT_LINES),''',
      '''     "Off = the combat and element charms add nothing (SkyyGear applies their stats).",          # 0.5.32: the element lines would overflow the help''')
P.rep('''    for li, b in enumerate(BOOSTERS):
        for t in range(1, 5):
            want[LINE_IDS[li * 4 + t - 1]] = OWN_ICON[(b[0], t)]''', '''    for li, b in enumerate(BOOSTERS):
        if b[0] in ELEM_LINES:          # 0.5.32: the element lines keep vanilla crystal icons (checked as "other items" below)
            continue
        for t in range(1, 5):
            want[LINE_IDS[li * 4 + t - 1]] = OWN_ICON[(b[0], t)]''')
P.rep('assert _n22 == 15, _n22',
      'assert _n22 == 15 + 18, _n22          # 0.5.32: + the six element lines x 3 steps')
assert P.s.count("registerSystem(") == SYS0 and P.s.count("registerCommand(") == CMD0, "0.5.32 adds no system / command"
P.finish()
